import ast,copy,hashlib,json,difflib
from pathlib import Path
p=json.loads(Path('proposal.json').read_text())
r=json.loads(Path('runtime.json').read_text())
# Validate the supplied study schema without installing packages.
def validate(x,s,path='"'$'"'):
 t=s.get('type')
 if t:
  types={'object':dict,'array':list,'string':str,'boolean':bool}
  assert isinstance(x,types[t]),(path,'type',t)
 if 'const' in s: assert x==s['const'],(path,'const')
 if 'enum' in s: assert x in s['enum'],(path,'enum')
 if isinstance(x,str): assert len(x)>=s.get('minLength',0),(path,'minLength')
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),(path,'minItems')
  for i,v in enumerate(x): validate(v,s.get('items',{}),path+'['+str(i)+']')
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'required')
  if s.get('additionalProperties') is False: assert set(x)<=set(s.get('properties',{})),(path,'extra')
  for k,v in x.items(): validate(v,s.get('properties',{}).get(k,{}),path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
parent=ast.parse(Path('history_g2_r0089_summary_terminal_bridge.py').read_text())
parent_class=next(n for n in parent.body if isinstance(n,ast.ClassDef) and n.name=='Model')
parent_methods={n.name:n for n in parent_class.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
parent_functions={n.name:n for n in parent.body if isinstance(n,ast.FunctionDef)}
def dump(n):return ast.dump(n,include_attributes=False)
for v in p['variants']:
 path=Path(v['file']); assert path.name==v['file'] and path.suffix=='.py'
 text=path.read_text();tree=ast.parse(text);compile(tree,str(path),'exec')
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert config==v['config']
 assert hashlib.sha256(text.encode()).hexdigest() in v['note']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 assert set(methods)==set(parent_methods)
 for name in methods:
  if name not in ('__init__','_represent'):assert dump(methods[name])==dump(parent_methods[name]),name
 for name,fn in parent_functions.items():
  assert dump(fn)==dump(next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name==name)),name
 # All parameter construction, reset and device placement remain verbatim.
 src=ast.get_source_segment(text,methods['__init__'])
 old=ast.get_source_segment(Path('history_g2_r0089_summary_terminal_bridge.py').read_text(),parent_methods['__init__'])
 assert src[src.index('self.compression_routes ='):]==old[old.index('self.compression_routes ='):]
 # Model input/embedding/summary/union/pool code differs only at phase selection.
 m=copy.deepcopy(methods['_represent']);o=copy.deepcopy(parent_methods['_represent'])
 for node in (m,o):
  node.body=[n for n in node.body if not (isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='moment_order' for t in n.targets))]
 assert dump(m)==dump(o)
 fn=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='_select_terminal_pair_order')
 env={};exec(compile(ast.Module(body=[fn],type_ignores=[]),'<phase dispatch>','exec'),env)
 sentinels={(a,b):object() for a in (False,True) for b in (False,True)}
 original=sentinels.copy()
 for training in (False,True):
  for train_flag in (False,True):
   for eval_flag in (False,True):
    result=env['_select_terminal_pair_order'](sentinels,training,train_flag,eval_flag)
    assert result is sentinels[(train_flag if training else eval_flag,False)]
 assert sentinels==original
 args=methods['__init__'].args
 defaults=dict(zip([a.arg for a in args.args][-len(args.defaults):],[ast.literal_eval(d) for d in args.defaults]))
 assert defaults['terminal_pair_train_shuffle']==config['terminal_pair_train_shuffle']
 assert defaults['terminal_pair_eval_shuffle']==config['terminal_pair_eval_shuffle']
 assert defaults['terminal_within_shuffle'] is False and config['terminal_within_shuffle'] is False
 for node in ast.walk(tree):
  if isinstance(node,ast.Import):
   assert all(a.name.split('.')[0] in ('torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo') for a in node.names)
  elif isinstance(node,ast.ImportFrom):assert node.module.split('.')[0] in ('torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo')
 print(v['name']+': syntax, config/defaults, phase truth table, inherited methods/functions, parameter construction, loss and transport AST checks passed')
left=Path(p['variants'][0]['file']).read_text().splitlines()
right=Path(p['variants'][1]['file']).read_text().splitlines()
print('Variant source differences:')
for l in difflib.unified_diff(left,right,n=0):
 if l.startswith(('+CONFIG','-CONFIG')): print(l[:30]+' [literal phase flag differences only, checked below]')
 else:print(l)
lcfg=p['variants'][0]['config'].copy();rcfg=p['variants'][1]['config'].copy()
assert {k for k in lcfg if lcfg[k]"'!=rcfg[k]}=={'"'terminal_pair_train_shuffle','terminal_pair_eval_shuffle'}
print('study_schema: passed; references: passed; standalone modules: passed; tensor/host gates: NOT RUN (torch unavailable)')
